// Order-8 IIR, TRANSPOSED feedforward chain: one multiply+add per stage
// (registered partial sums) + a tiny feedback stage -> critical path roughly
// independent of the order -> high Fmax. Same function as the direct form.
module iir8_v7 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [15:0] r1;
  reg [15:0] r2;
  reg [15:0] r3;
  reg [15:0] r4;
  reg [15:0] r5;
  reg [15:0] r6;
  reg [15:0] r7;
  reg [15:0] r8;
  reg [15:0] y2;
  wire [31:0] acc = 57*x + 40*r1 + 15*r2 + 4*r3 + 33*r4 + 61*r5 + 39*r6 + 57*r7 + 30*r8 + ((9*y)>>4) + ((5*y2)>>4);
  always @(posedge clk) begin
    if (!rst_n) begin y<=0; y2<=0; r1<=0; r2<=0; r3<=0; r4<=0; r5<=0; r6<=0; r7<=0; r8<=0; end
    else begin
      y <= acc[15:0];
      y2 <= y;
      r1 <= (40*x + 33*r2 + 61*r3 + 39*r4 + 57*r5 + 30*r6 + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF;
      r2 <= (15*x + 4*r3 + 30*r4 + 5*r5 + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF;
      r3 <= (4*x + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF;
      r4 <= (33*x + 57*r1 + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF;
      r5 <= (61*x + 39*r1 + 40*r2 + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF;
      r6 <= (39*x + 57*r1 + 15*r2 + 4*r3 + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF;
      r7 <= (57*x + 30*r1 + 4*r2 + 33*r3 + 61*r4 + 39*r5 + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF;
      r8 <= (30*x + 5*r1 + 39*r2 + 15*r3 + 4*r4 + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF;
    end
  end
endmodule
